export const getAvailableCitiesForService = (service: string): string[] => {
  if (!service) return [...new Set(agencies.map(agency => agency.ville))];
  
  const filteredAgencies = agencies.filter(agency => {
    switch (service) {
      case "narsa":
        return agency.narsa;
      case "cnss":
        return agency.cnss;
      case "amana":
        return agency.amana;
      case "change":
        return agency.change;
      case "baridESign":
        return agency.baridESign;
      default:
        return true;
    }
  });
  
  return [...new Set(filteredAgencies.map(agency => agency.ville))];
};

export const getFilteredAgencies = (service: string, city: string, location: string): Agency[] => {
  let filtered = agencies;
  
  // Filter by service
  if (service) {
    filtered = filtered.filter(agency => {
      switch (service) {
        case "narsa":
          return agency.narsa;
        case "cnss":
          return agency.cnss;
        case "amana":
          return agency.amana;
        case "change":
          return agency.change;
        case "baridESign":
          return agency.baridESign;
        default:
          return true;
      }
    });
  }
  
  // Filter by city
  if (city) {
    filtered = filtered.filter(agency => agency.ville === city);
  }
  
  // Filter by location (search in agency name and address)
  if (location) {
    const searchTerm = location.toLowerCase();
    filtered = filtered.filter(agency => 
      agency.agence.toLowerCase().includes(searchTerm) ||
      agency.adresse.toLowerCase().includes(searchTerm)
    );
  }
  
  return filtered;
};

